require'json';require'find';require'fileutils';root=File.expand_path('..',__dir__);trees=[root,File.expand_path('../Client',root)];skip=%r{/(?:\.git|target|build|work|logs|node_modules|temp|library)(?:/|$)}i;text_ext=%w[.java .kt .ts .tsx .js .mjs .cjs .json .xml .properties .yml .yaml .md .txt .csv .sql .sh .rb .py .conf .ini .toml .proto .gradle .bat .cmd .url .meta .prefab .scene .plist .html .css .scss];crlf=[];bare_cr=[];count=0;trees.each{|tree|Find.find(tree){|p|if File.directory?(p)&&p!=tree&&p.match?(skip);Find.prune;next;end;next unless File.file?(p)&&text_ext.include?(File.extname(p).downcase);bytes=File.binread(p);next unless bytes.dup.force_encoding('UTF-8').valid_encoding?;count+=1;rel=p.delete_prefix(tree+'/');crlf<<rel if bytes.include?("\r\n");bare_cr<<rel if bytes.gsub("\r\n",'').include?("\r")}};result={task:'FS05',passed:crlf.empty?&&bare_cr.empty?,policy:'LF',scannedTextFiles:count,crlfFiles:crlf.sort,bareCarriageReturnFiles:bare_cr.sort};out=File.join(root,'docs/generated/fs05-line-endings.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(result)+"\n");abort("FS05 CRLF=#{crlf.length}, bareCR=#{bare_cr.length}")unless result[:passed]
